{
  "definition_simple": "传本，指流传下来的版本。",
  "definition_standard": "某一文献在流传过程中产生的版本，通常指古籍的抄本或刻本，与原稿或佚失版本相对。",
  "pos": "名词",
  "semantic_class": "concrete",
  "sentences": [
    {"text": "这本书有多个传本。", "difficulty": "T1"},
    {"text": "图书馆收藏了很多古籍传本。", "difficulty": "T2"},
    {"text": "该文献的传本在明清时期广为流传。", "difficulty": "T3"},
    {"text": "学者们通过比较不同传本来校勘文字正误。", "difficulty": "T4"},
    {"text": "这部小说的传本差异反映了刻本与抄本的不同。", "difficulty": "T5"},
    {"text": "《尚书》的传本问题一直是经学研究的热点。", "difficulty": "T6"},
    {"text": "敦煌写本的传本对研究唐代文学非常重要。", "difficulty": "T3"},
    {"text": "对于传本的整理工作需要跨学科合作。", "difficulty": "T4"},
    {"text": "早期传本中保存了许多后世佚失的篇章。", "difficulty": "T5"},
    {"text": "传本系统的构建有助于理解文献的演变过程。", "difficulty": "T6"}
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {
      "word": "全本",
      "explanation": "全本与传本声母不同（q vs ch），但韵母相同，在快速语音中容易混淆。"
    },
    {
      "word": "船本",
      "explanation": "船本与传本读音完全相同（chuán běn），仅字形不同，学习中易写错。"
    },
    {
      "word": "传版",
      "explanation": "传版韵母为an，传本韵母为en，在前后鼻音不分的声音中极易混淆。"
    }
  ],
  "primary_collocate": "古籍",
  "collocation_distractors": [
    {
      "word": "小说",
      "explanation": "小说虽有传本，但“小说传本”并非固定搭配，通常只说“小说版本”。"
    },
    {
      "word": "文献",
      "explanation": "文献范围广泛，传本是文献的一种，但“文献传本”不符合惯用表达。"
    },
    {
      "word": "原稿",
      "explanation": "原稿与传本语义相对（原始 vs 流传），并非自然搭配。"
    }
  ],
  "collocation_wrong_collocate": {
    "word": "底本",
    "explanation": "底本指校勘时依据的版本，与传本意义有交叉，但“传本底本”作为并列短语不成立，因为二者概念不同。"
  },
  "cloze_distractors": [
    {
      "word": "原稿",
      "explanation": "原稿指原始手稿，而句子需要的是流传版本的词，语义相反。"
    },
    {
      "word": "稿本",
      "explanation": "稿本多指书籍的底稿，与传本（流传版本）不是同一概念。"
    },
    {
      "word": "伪本",
      "explanation": "伪本指伪造的版本，并不等同于真实流传的版本。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "这篇传本包含了许多珍贵信息。",
      "reason": "量词错误：“篇”通常用于文章，传本应使用“本”或“种”。"
    },
    {
      "sentence": "传本的使用方法很简单。",
      "reason": "动宾搭配不当：“使用”适用于工具，传本通常被研究、整理、校勘，而非“使用”。"
    },
    {
      "sentence": "这本传本很便宜。",
      "reason": "语义失当：传本多指古籍，强调文献价值，一般不以价格高低评价，且现代商品语义不匹配。"
    }
  ],
  "spot_incorrect": {
    "sentence": "他收集了三本传本文献。",
    "error_description": "语义重复：“传本”本身就是文献的一种，与“文献”并列造成冗余。",
    "correction": "他收集了三本传本。"
  },
  "word_family_forms": [],
  "word_family_fake_forms": [
    {
      "form": "传本化",
      "explanation": "看起来像动词派生名词（如‘现代化’），但‘传本’无此派生用法。"
    },
    {
      "form": "传本主义",
      "explanation": "模仿‘人道主义’等造词，但实际不存在。"
    },
    {
      "form": "传本家",
      "explanation": "仿‘作家’、‘艺术家’，加后缀‘家’表示从事者，但无此称呼。"
    }
  ],
  "syn_ant_candidates": [
    {"word": "版本", "type": "synonym"},
    {"word": "抄本", "type": "synonym"},
    {"word": "刻本", "type": "synonym"},
    {"word": "原本", "type": "antonym"}
  ],
  "particle_candidates": null
}
